* { box-sizing: border-box; }
body { margin: 0; color: #202938; background: #f5f7fb; font: 16px/1.5 system-ui, sans-serif; }
.container { max-width: 760px; margin: 48px auto; padding: 0 24px; }
.header { border-bottom: 1px solid #dce2eb; margin-bottom: 28px; }
h1 { font-size: 2rem; margin: 0 0 18px; }
h1 a { color: inherit; text-decoration: none; }
h2 { font-size: 1.35rem; margin: 0 0 20px; }
form { padding: 20px; background: white; border: 1px solid #dce2eb; border-radius: 8px; }
label { display: block; font-weight: 600; margin-bottom: 8px; }
.create-controls { display: flex; gap: 10px; }
input { flex: 1; min-width: 0; padding: 10px 12px; border: 1px solid #aeb9c9; border-radius: 5px; font: inherit; }
select { display: block; margin: 8px 0 16px; padding: 9px 12px; border: 1px solid #aeb9c9; border-radius: 5px; font: inherit; }
.task-row { display: flex; justify-content: space-between; align-items: center; gap: 16px; padding: 12px 18px; margin-top: 10px; background: white; border: 1px solid #dce2eb; border-radius: 7px; }
.task-row input { flex: 0 0 auto; width: 18px; height: 18px; }
#task-error-message { margin: 10px 0 0; color: #a32121; }
button { padding: 10px 15px; color: white; background: #275dad; border: 0; border-radius: 5px; font: inherit; cursor: pointer; }
button:hover { background: #1b4787; }
.project-row { display: flex; justify-content: space-between; align-items: center; gap: 16px; padding: 15px 18px; margin-top: 12px; background: white; border: 1px solid #dce2eb; border-radius: 7px; }
#error-message { margin: 10px 0 0; color: #a32121; }
#project-detail > button { margin-bottom: 20px; }
#project-detail h2 { font-size: 1.8rem; }
@media (max-width: 500px) { .container { margin-top: 24px; } .create-controls { flex-direction: column; } }

